  // 1. Connect to the SQLite database "test_db.sqlite"
  auto conn = sqlite::connect("test_db.sqlite");

  // 2. Begin transaction to ensure safety
  auto trans = begin_transaction(conn);

  // 3. Delete users who have not logged in since 2025-01-01
  // WHERE last_login < DATE('2025-01-01')
  auto delete_op = delete_from<User> | where(col<"last_login"> < DateTime{"2025-01-01"});
  auto deleted = delete_op(trans);

  // 4. Commit the transaction
  auto result = commit(deleted);

  // 5. Return operation result (0 for success, 1 for failure)
  return result ? 0 : 1;
}

