                      WhereType,
                      transpilation::group_by_t<TableOrQueryType,
                                                typename ColTypes::ColType...>,
                      OrderByType, LimitType, ToType>{.fields_ = _s.fields_,
                                                      .from_ = _s.from_,
                                                      .joins_ = _s.joins_,
