    static_assert(std::is_same_v<LimitType, Nothing>,
                  "You cannot call limit(...) before group_by(...).");
    static_assert(std::is_same_v<ToType, Nothing>,
                  "You cannot call to<...> before group_by(...).");
    static_assert(sizeof...(ColTypes) != 0,
