    // Build the query with self-join
    // - select_from<Employee, "t1"> creates the main table with alias "t1" (e1)
    // - "name"_t1 refers to name column from table alias "t1"
    // - "name"_t2 refers to name column from table alias "t2"
    // - as<"employee"> and as<"manager"> rename the columns
    // - left_join<Employee, "t2"> joins Employee table again with alias "t2" (e2)
    // - "manager_id"_t1 == "emp_id"_t2 is the join condition (e1.manager_id = e2.emp_id)
    // - to<std::vector<EmployeeManager>> specifies the return type
    auto query = select_from<Employee, "t1">(
        "name"_t1 | as<"employee">,
        "name"_t2 | as<"manager">
