  sqlgen::PrimaryKey<int> user_id;
  std::string trimmed_name;
  std::string trimmed_email;
  int name_length;
  int email_length;
};

/**
 * description: trim_and_length_validation.
 * This function demonstrates how to trim whitespace from string columns and validate their lengths using sqlgen read API.
 * It returns a vector of ValidatedProfile structs, where each struct contains the user_id, trimmed_name, trimmed_email, name_length, and email_length.
 * Returns: std::vector<ValidatedProfile>.
 */
std::vector<ValidatedProfile> trim_and_length_validation() {
  // Connect to the SQLite database
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Read all UserProfile records from the database
  auto profiles_result = conn | sqlgen::read<std::vector<UserProfile>>;

  std::vector<ValidatedProfile> results;

  // Process the result using the Result monad pattern
  profiles_result.and_then([&results](const std::vector<UserProfile>& profiles) {
    // Helper function to trim whitespace from strings
    // This demonstrates the concept of trim, ltrim, rtrim operations
    auto trim_string = [](const std::string& str) -> std::string {
      if (str.empty()) return str;

      // ltrim - remove leading whitespace
      size_t start = str.find_first_not_of(" \t\n\r\f\v");
      if (start == std::string::npos) return "";

      // rtrim - remove trailing whitespace
      size_t end = str.find_last_not_of(" \t\n\r\f\v");

      // trim - combine ltrim and rtrim
      return str.substr(start, end - start + 1);
    };

    // Transform each UserProfile to ValidatedProfile
    for (const auto& profile : profiles) {
      ValidatedProfile validated;
      validated.user_id = profile.user_id;

      // Apply trim operations to name and email
      validated.trimmed_name = trim_string(profile.name);
      validated.trimmed_email = trim_string(profile.email);

      // Compute length of trimmed strings
      validated.name_length = static_cast<int>(validated.trimmed_name.length());
      validated.email_length = static_cast<int>(validated.trimmed_email.length());

      results.push_back(validated);
    }

    return sqlgen::Result<int>(0);
  });

  return results;
}

}  // namespace trim_and_length_validation
