    return select_from_impl<TableTupleType, AliasType, FieldsType,
                            TableOrQueryType, JoinsType, WhereType, GroupByType,
                            OrderByType, LimitType, ContainerType>(
        _conn, _fields, _table_or_query, _joins, _where, _limit);
