  conn->template create_table<Department>("Department");
  conn->template create_table<Employee>("Employee");

  // Insert data
  for (const auto& dept : depts) {
    conn->insert("Department", dept);
  }
  for (const auto& emp : emps) {
    conn->insert("Employee", emp);
