/**
 * analyze_department_employees
 * Provides data-join analysis between Department and Employee input collections by
 * creating temporary SQL tables, inserting the provided rows, and executing a
 * variety of join queries to produce join-output samples.
 * Returns: JoinAnalysis.
 */
JoinAnalysis analyze_department_employees_impl(const std::vector<Department>& depts, const std::vector<Employee>& emps) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to SQLite database
  auto conn_result = sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    return JoinAnalysis{};
  }
  auto conn = *conn_result;

  // Create tables (drop if exists to ensure clean state)
  conn->execute("DROP TABLE IF EXISTS Employee");
  conn->execute("DROP TABLE IF EXISTS Department");
  conn->create_table<Department>("Department");
  conn->create_table<Employee>("Employee");

  // Insert department data
  for (const auto& dept : depts) {
    conn->insert("Department", dept);
  }

  // Insert employee data
  for (const auto& emp : emps) {
    conn->insert("Employee", emp);
  }

  JoinAnalysis result;

  // INNER JOIN: Department (t1) INNER JOIN Employee (t2)
  // SELECT d.department_name, e.first_name, e.last_name, e.salary
  // FROM Department d INNER JOIN Employee e ON d.department_id = e.department_id
  auto inner_query = select_from<Department, "d">(
    "department_name"_t1, 
    "first_name"_t2, 
    "last_name"_t2, 
    "salary"_t2
  ) | inner_join<Employee, "e">("department_id"_t1 == "department_id"_t2)
    | to<std::vector<JoinResult>>;

  if (auto inner_result = inner_query(conn)) {
    result.inner_join_results = std::move(*inner_result);
  }

  // LEFT JOIN: Employee (t1) LEFT JOIN Department (t2)
  // SELECT d.department_name, e.first_name, e.last_name, e.salary
  // FROM Employee e LEFT JOIN Department d ON e.department_id = d.department_id
  auto left_query = select_from<Employee, "e">(
    "department_name"_t2,
    "first_name"_t1,
    "last_name"_t1,
    "salary"_t1
  ) | left_join<Department, "d">("department_id"_t1 == "department_id"_t2)
    | to<std::vector<JoinResult>>;

  if (auto left_result = left_query(conn)) {
    result.left_join_results = std::move(*left_result);
  }

  // RIGHT JOIN: Employee (t1) RIGHT JOIN Department (t2)
  // SELECT d.department_name, e.first_name, e.last_name, e.salary
  // FROM Employee e RIGHT JOIN Department d ON e.department_id = d.department_id
  auto right_query = select_from<Employee, "e">(
    "department_name"_t2,
    "first_name"_t1,
    "last_name"_t1,
    "salary"_t1
  ) | right_join<Department, "d">("department_id"_t1 == "department_id"_t2)
    | to<std::vector<JoinResult>>;

  if (auto right_result = right_query(conn)) {
    result.right_join_results = std::move(*right_result);
  }

  // FULL JOIN: Employee (t1) FULL JOIN Department (t2)
  // Includes all employees and all departments
  auto full_query = select_from<Employee, "e">(
    "department_name"_t2,
    "first_name"_t1,
    "last_name"_t1,
    "salary"_t1
  ) | full_join<Department, "d">("department_id"_t1 == "department_id"_t2)
    | to<std::vector<JoinResult>>;

  if (auto full_result = full_query(conn)) {
    result.full_join_results = std::move(*full_result);
  }

  return result;
}

}  // namespace analyze_department_employees
