                                 .from_ = _s.from_,
                                 .joins_ = _s.joins_,
                                 .where_ = _s.where_,
                                 .limit_ = _s.limit_};
  }

  FieldsType fields_;

  TableOrQueryType from_;

  JoinsType joins_;

  WhereType where_;

  LimitType limit_;
};

