TEST(sqlite, weekday_sales_analysis) {
  using namespace sqlgen;
  auto conn = sqlite::connect("test_db.sqlite").value();
  drop<Sales>(conn);
  create_table<Sales>(conn);
  insert(conn, std::vector<Sales>{
      {1, 10, 2, sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S">{"2024-01-01 09:00:00"}},
      {2, 11, 3, sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S">{"2024-01-02 09:00:00"}},
      {3, 12, 1, sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S">{"2024-01-03 09:00:00"}}});
  auto rows = weekday_sales_analysis();
  ASSERT_GE(rows.size(), 1);
